// Builds supabase/SETUP-ALL-IN-ONE.sql from supabase/migrations (run: npm run sql:bundle)
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
const dir = "supabase/migrations";
const parts = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort()
  .map((f) => `-- ===================== ${f} =====================\n` + readFileSync(`${dir}/${f}`, "utf8"));
writeFileSync("supabase/SETUP-ALL-IN-ONE.sql",
  "-- Sanghu database setup. GENERATED by `npm run sql:bundle` from supabase/migrations - do not edit by hand.\n" +
  "-- Run ONCE on a NEW, EMPTY Supabase project: SQL Editor -> New query -> paste everything -> Run.\n\n" + parts.join("\n\n"));
console.log("wrote supabase/SETUP-ALL-IN-ONE.sql");
